function AdmissionLifecycleActions({patient,admission,tenantId,isDemo,departments,canEdit,showPatientActions,onDeleted,onChanged,t,language}){const {notify}=useFeedback();const [kind,setKind]=useState(null),[busy,setBusy]=useState(false),[draft,setDraft]=useState({date:new Date().toISOString().slice(0,10),departmentId:'',reason:''});const open=next=>{setDraft({date:new Date().toISOString().slice(0,10),departmentId:'',reason:''});setKind(next)};async function save(){if(!draft.date)return;try{setBusy(true);if(kind==='discharge')await dischargeAdmission(tenantId,patient,admission,draft,{isDemo});else{const dept=departments.find(x=>x.id===draft.departmentId);await transferAdmission(tenantId,patient,admission,{...draft,department:dept?.name||''},{isDemo})}setKind(null);await onChanged?.();notify(t('saved'),'success')}catch(error){notify(error?.message||t('actionFailed'),'danger')}finally{setBusy(false)}}const lifecycleItems=canEdit&&admission.status==='active'?[{id:'transfer',label:language==='el'?'Μεταφορά σε άλλο τμήμα':'Transfer to another department',icon:ArrowRightLeft,onClick:()=>open('transfer')},{id:'discharge',label:language==='el'?'Εξιτήριο':'Discharge',icon:LogOut,onClick:()=>open('discharge')}]:[];return <>{showPatientActions?<PatientSummaryActions patient={patient} departments={departments} onReload={onChanged} onDeleted={onDeleted} extraItems={lifecycleItems}/>:lifecycleItems.length?<OverflowMenu label={language==='el'?'Ενέργειες νοσηλείας':'Admission actions'} items={lifecycleItems}/>:null}{kind&&<SimpleDialog title={kind==='transfer'?(language==='el'?'Μεταφορά ασθενούς':'Transfer patient'):(language==='el'?'Εξιτήριο ασθενούς':'Discharge patient')} t={t} onClose={()=>setKind(null)} onSave={save} disabled={busy||!draft.date||(kind==='transfer'&&!draft.departmentId)}><ManualDateField label={kind==='transfer'?(language==='el'?'Ημερομηνία μεταφοράς':'Transfer date'):(language==='el'?'Ημερομηνία εξιτηρίου':'Discharge date')} value={draft.date} onChange={v=>setDraft(d=>({...d,date:v}))}/>{kind==='transfer'&&<label><span>{language==='el'?'Νέο τμήμα':'New department'}</span><select value={draft.departmentId} onChange={e=>setDraft(d=>({...d,departmentId:e.target.value}))}><option value="">{t('select')}</option>{departments.filter(x=>x.id!==admission.departmentId).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label>}<label className="entry-span-2"><span>{t('reason')}</span><textarea rows={3} value={draft.reason} onChange={e=>setDraft(d=>({...d,reason:e.target.value}))}/></label></SimpleDialog>}</>}
function Summary({label,value,tone='neutral'}){return <div className={`patient-summary-item ${tone}`}><span>{label}</span><strong>{value}</strong></div>}
