function sampleParentCode(sample){const code=String(sample?.id||'');return /-R\d+$/.test(code)?code.replace(/-R\d+$/,''):''}
function SampleTree({samples=[],linked,onFollowUp,onCreateFromSample,canCreate,canCreateSample,t,language,fmtDate}){const codes=new Set(samples.map(x=>String(x.id||'')));const roots=samples.filter(x=>!sampleParentCode(x)||!codes.has(sampleParentCode(x)));const render=(sample,depth=0)=><div data-sample-root={depth===0?'true':undefined} key={sample.recordId||sample.id}><SampleTreeRow sample={sample} linked={linked} depth={depth} onFollowUp={onFollowUp} onCreateFromSample={onCreateFromSample} canCreate={canCreate} canCreateSample={canCreateSample} t={t} language={language} fmtDate={fmtDate}/>{samples.filter(x=>sampleParentCode(x)===String(sample.id||'')).map(child=>render(child,depth+1))}</div>;return <>{roots.map(x=>render(x,0))}</>}
function SampleTreeRow({sample,linked,depth=0,onFollowUp,onCreateFromSample,canCreate,canCreateSample,t,language,fmtDate}){const type=t(sample.sampleType||sample.type)||(sample.sampleType||sample.type||'—');const status=t(sample.result||sample.status||'pending');const organism=sample.organism||sample.microorganism||sample.microbiologyResults?.find(x=>x.organism)?.organism||'—';const amr=sample.resistance||sample.amr||sample.microbiologyResults?.find(x=>x.amr)?.amr||'—';const isNegative=sample.result==='negative';return <div className={`surveillance-tree-sample ${linked?'is-linked':'is-unlinked'} ${depth?'is-followup':''}`} style={{paddingLeft:`${linked?32:depth*28}px`}}><span>{depth>0&&<i aria-hidden="true">↳</i>}<span><strong>{fmtDate(sample.collectedAt||sample.requestedAt)}</strong><small>{depth?(language==='el'?`Επανέλεγχος ${depth}`:`Follow-up ${depth}`):type} · {type}{sample.id?` · ${sample.id}`:''}</small></span></span><span>{status}</span><span>{organism}</span><span>{amr}</span><span className="surveillance-sample-actions">{linked?<em>{language==='el'?'Συνδεδεμένο':'Linked'}</em>:isNegative?<em className="sample-negative-note" title={language==='el'?'Ένα αρνητικό αποτέλεσμα δεν μπορεί να ξεκινήσει επιτήρηση.':'A negative result cannot start a surveillance case.'}>{language==='el'?'Αρνητικό — καμία επιτήρηση':'Negative — no surveillance'}</em>:(canCreate?<Button className="sample-start-action" variant="secondary" onClick={()=>onCreateFromSample?.(sample)}><PlayCircle size={14}/>{language==='el'?'Έναρξη επιτήρησης':'Start surveillance'}</Button>:null)}{canCreateSample&&<Button className="sample-followup-action" variant="secondary" onClick={()=>onFollowUp?.(sample)}><RefreshCcw size={14}/>{language==='el'?'Επανέλεγχος':'Follow-up'}</Button>}</span></div>}

function CanonicalJourney({record,repository,libraries={},organizationId,isDemo,onLibraryAdded,onReload,t,language,fmtDate,fmtDateTime,permissions}){const {notify}=useFeedback();const [stage,setStage]=useState('assessment'),[dialog,setDialog]=useState(null),[reason,setReason]=useState(''),[entryDetail,setEntryDetail]=useState(null);const active=record.status==='active';async function run(work,message){try{await work();setDialog(null);setReason('');await onReload();notify(message||t('actionCompleted'),'success')}catch(error){notify(error?.message||t('actionFailed'),'danger')}}if(!active)return <div className="clinical-data-hub"><div className="clinical-data-heading"><div><span className="eyebrow">{t('surveillance')}</span><h3>{t('clinicalRecords.completedSurveillance')}</h3></div>{permissions.canReopen&&<Button variant="secondary" onClick={()=>setDialog('reopen')}><RefreshCcw size={15}/>{t('clinicalRecords.reopenSurveillance')}</Button>}</div><CompletedReport record={record} t={t} fmtDate={fmtDate} fmtDateTime={fmtDateTime}/>{dialog==='reopen'&&<ReasonDialog title={t('clinicalRecords.reopenSurveillance')} t={t} reason={reason} setReason={setReason} onClose={()=>setDialog(null)} onSave={()=>run(()=>repository.reopen(record,reason),t('clinicalRecords.surveillanceUpdated'))}/>}</div>;return <div className="clinical-data-hub"><div className="journey-heading episode-journey-heading"><div><span className="eyebrow">{t('surveillanceJourney')}</span><h3 className="journey-case-id">{record.id}</h3><p>{t('clinicalRecords.strictActiveJourneyHelp')}</p></div></div><SurveillanceJourneyGuidance record={record} t={t} canAssess={permissions.canAssess} canLab={permissions.canLab} canIsolation={permissions.canIsolation} canTherapy={permissions.canTherapy} canReassess={permissions.canReassess} onSelect={setStage}/><SurveillanceJourneyMap record={record} t={t} fmtDate={fmtDate} activeStage={stage} onSelect={setStage}/><div className="clinical-data-grid">{stage==='assessment'&&<StagePanel icon={ShieldCheck} title={t('clinicalAssessment')} action={permissions.canAssess?<Button className="clinical-stage-action" variant="secondary" onClick={()=>setDialog('assessment')}>{record.assessment?(language==='el'?'Επεξεργασία αξιολόγησης':'Edit assessment'):(language==='el'?'Νέα κλινική αξιολόγηση':'New clinical assessment')}</Button>:null}>{record.assessment?<><div className="detail-grid"><Detail label={t('assessmentDate')} value={fmtDate(record.assessment.date)}/><Detail label={t('classification')} value={t(record.assessment.classification||'undetermined')}/></div><p className="clinical-summary">{record.assessment.summary||record.assessment.notes||'—'}</p><TagList title={t('signsSymptoms')} items={record.assessment.signsSymptoms||record.assessment.symptoms} t={t} language={language}/><TagList title={t('riskFactors')} items={record.assessment.riskFactors} t={t} language={language}/></>:<div className="inline-empty">{t('clinicalRecords.assessmentPending')}</div>}</StagePanel>}{stage==='devices'&&<StagePanel icon={Stethoscope} title={language==='el'?'Συσκευές & παράγοντες κινδύνου':'Devices & risk factors'} action={permissions.canAssess?<Button className="clinical-stage-action" variant="secondary" onClick={()=>setDialog('device')}>{language==='el'?'Καταχώριση συσκευής':'Record device'}</Button>:null}>{record.devices?.length?<div className="record-table-wrap"><table className="record-table"><thead><tr><th>{language==='el'?'Συσκευή':'Device'}</th><th>{language==='el'?'Ημερομηνία έναρξης':'Start date'}</th><th>{t('status')}</th></tr></thead><tbody>{record.devices.map(x=><tr key={x.id}><td>{x.name||x.type||'—'}</td><td>{fmtDate(x.insertedAt||x.startedAt)}</td><td>{t(x.status||'active')}</td></tr>)}</tbody></table></div>:<div className="inline-empty">{language==='el'?'Δεν έχουν καταγραφεί επεμβατικές συσκευές. Οι παράγοντες κινδύνου καταγράφονται επίσης στην κλινική αξιολόγηση.':'No invasive devices recorded. Risk factors are also documented in the clinical assessment.'}</div>}</StagePanel>}{stage==='samples'&&<StagePanel icon={Microscope} title={t('samples')} action={permissions.canLab?<Button className="clinical-stage-action" variant="secondary" onClick={()=>setDialog('sample')}>{language==='el'?'Νέο δείγμα':'New sample'}</Button>:null}>{record.samples?.length?<div className="record-table-wrap"><table className="record-table"><thead><tr><th>{t('sampleType')}</th><th>{t('status')}</th><th>{t('organism')}</th><th>{language==='el'?'AMR – Αντοχή':'AMR – Resistance'}</th></tr></thead><tbody>{record.samples.map(x=><tr key={x.id} className="clickable-row" tabIndex={0} onClick={()=>setEntryDetail({kind:'sample',row:x})} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setEntryDetail({kind:'sample',row:x})}}}><td>{t(x.type)||x.type}</td><td>{t(x.result||x.status||'pending')}</td><td>{x.organism||'—'}</td><td>{x.resistance||'—'}</td></tr>)}</tbody></table></div>:<div className="inline-empty">{t('clinicalRecords.noSamplesRecorded')}</div>}</StagePanel>}{stage==='hai'&&<StagePanel icon={AlertTriangle} title={language==='el'?'HAI – Λοιμώξεις σχετιζόμενες με φροντίδα / AMR – Αντοχή στα αντιμικροβιακά':'HAI – Healthcare-associated infections / AMR – Antimicrobial resistance'} action={permissions.canAssess?<Button className="clinical-stage-action" variant="secondary" onClick={()=>setDialog('hai')}>{language==='el'?'Νέα αξιολόγηση HAI':'New HAI assessment'}</Button>:null}>{record.haiClassification?<div className="evidence-box"><strong>{record.haiClassification.type||'—'} · {t(record.haiClassification.status)}</strong><span>{record.haiClassification.rationale||record.haiClassification.definitionSet||'—'}</span></div>:<div className="inline-empty">{t('clinicalRecords.notDocumented')}</div>}{record.resistance?<div className="evidence-box"><strong>{record.resistance}</strong><span>{language==='el'?'Παράγεται από επικυρωμένα μικροβιολογικά/AST δεδομένα.':'Derived from validated microbiology/AST evidence.'}</span></div>:<div className="inline-empty">{language==='el'?'Δεν υπάρχει ακόμη τεκμηριωμένη ταξινόμηση MDR/XDR/PDR (πολυανθεκτικότητα / εκτεταμένη αντοχή / παναντοχή) από επικυρωμένα δεδομένα AST – ελέγχου ευαισθησίας στα αντιμικροβιακά.':'No MDR/XDR/PDR classification is yet supported by validated AST evidence.'}</div>}</StagePanel>}{stage==='therapy'&&<StagePanel icon={Pill} title={t('therapy')} action={permissions.canTherapy?<Button className="clinical-stage-action" variant="secondary" onClick={()=>setDialog('therapy')}>{language==='el'?'Νέα αντιμικροβιακή αγωγή':'New antimicrobial therapy'}</Button>:null}>{record.therapy?.length?<div className="record-table-wrap"><table className="record-table"><tbody>{record.therapy.map(x=><tr key={x.id} className="clickable-row" tabIndex={0} onClick={()=>setEntryDetail({kind:'therapy',row:x})} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setEntryDetail({kind:'therapy',row:x})}}}><td><strong>{x.antimicrobial}</strong></td><td>{x.dose||'—'} · {x.route||'—'}</td><td>{fmtDate(x.startedAt)}</td><td>{t(x.status||'active')}</td></tr>)}</tbody></table></div>:<div className="inline-empty">{t('clinicalRecords.noTherapyRecorded')}</div>}</StagePanel>}{stage==='isolation'&&<StagePanel icon={BedDouble} title={t('isolation')} action={permissions.canIsolation?<div className="button-row">{record.isolation?.status==='active'?<Button variant="secondary" onClick={()=>setDialog('endIsolation')}>{t('end')}</Button>:<Button className="clinical-stage-action" variant="secondary" onClick={()=>setDialog('isolation')}>{language==='el'?'Έναρξη απομόνωσης':'Start isolation'}</Button>}{!record.isolation&&<Button variant="ghost" onClick={()=>run(()=>repository.setIsolationNotRequired(record),t('actionCompleted'))}>{t('notRequired')}</Button>}</div>:null}>{record.isolation?<div className="detail-grid"><Detail label={t('status')} value={t(record.isolation.status)}/><Detail label={t('startDate')} value={fmtDate(record.isolation.startedAt)}/><Detail label={t('reason')} value={record.isolation.reason}/><Detail label={t('room')} value={record.isolation.room}/></div>:<div className="inline-empty">{record.isolationDecision?.required===false?t('notRequired'):t('clinicalRecords.noIsolationRecorded')}</div>}</StagePanel>}{stage==='reassessment'&&<StagePanel icon={RefreshCcw} title={t('reassessment')} action={permissions.canReassess?<Button className="clinical-stage-action" variant="secondary" onClick={()=>setDialog('reassessment')}>{language==='el'?'Νέα επανεκτίμηση':'New reassessment'}</Button>:null}>{record.reassessments?.length?<div className="clinical-timeline">{record.reassessments.map(x=><article key={x.id} className="clickable-entry" tabIndex={0} onClick={()=>setEntryDetail({kind:'reassessment',row:x})} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setEntryDetail({kind:'reassessment',row:x})}}}><div><header><strong>{t(x.status)}</strong><time>{fmtDate(x.date)}</time></header><p>{x.notes||'—'}</p></div></article>)}</div>:<div className="inline-empty">{t('clinicalRecords.noReassessmentRecorded')}</div>}</StagePanel>}{stage==='outcome'&&<StagePanel icon={Activity} title={t('outcome')} action={permissions.canOutcome?<Button className="clinical-stage-action" variant="secondary" onClick={()=>setDialog('outcome')}>{record.outcome?t('edit'):`+ ${t('outcome')}`}</Button>:null}>{record.outcome?<div className="detail-grid"><Detail label={t('status')} value={t(record.outcome.status)}/><Detail label={t('date')} value={fmtDate(record.outcome.date)}/><Detail label={t('notes')} value={record.outcome.notes}/></div>:<div className="inline-empty">{t('clinicalRecords.notDocumented')}</div>}</StagePanel>}</div>{dialog==='assessment'&&<AssessmentDialog t={t} record={record} symptomRows={libraries.clinicalSymptoms||[]} riskRows={libraries.clinicalRiskFactors||[]} onClose={()=>setDialog(null)} onSave={draft=>run(()=>repository.saveAssessment(record,draft),t('actionCompleted'))}/>} {dialog==='device'&&<DeviceDialog t={t} items={libraries.deviceTypes||[]} onAddLibraryItem={item=>onLibraryAdded?.('deviceTypes',item)} onClose={()=>setDialog(null)} onSave={draft=>run(()=>repository.addDevice(record,draft),t('actionCompleted'))}/>} {dialog==='sample'&&<SampleDialog t={t} onClose={()=>setDialog(null)} onSave={draft=>run(()=>repository.requestSample(record,draft),t('actionCompleted'))}/>} {dialog==='hai'&&<HaiDialog t={t} items={libraries.surveillanceDefinitions||[]} organizationId={organizationId} isDemo={isDemo} onAddLibraryItem={item=>onLibraryAdded?.('surveillanceDefinitions',item)} onClose={()=>setDialog(null)} onSave={draft=>run(()=>repository.saveHai(record,draft),t('actionCompleted'))}/>} {dialog==='therapy'&&<TherapyDialog t={t} antibiotics={libraries.antibiotics||[]} advancedAntibiotics={libraries.advancedAntibiotics||[]} onClose={()=>setDialog(null)} onSave={draft=>run(()=>repository.addTherapy(record,draft),t('actionCompleted'))}/>} {dialog==='isolation'&&<IsolationDialog t={t} onClose={()=>setDialog(null)} onSave={draft=>run(()=>repository.beginIsolation(record,draft),t('actionCompleted'))}/>} {dialog==='endIsolation'&&<EndDialog title={t('isolation')} t={t} onClose={()=>setDialog(null)} onSave={draft=>run(()=>repository.finishIsolation(record,draft),t('actionCompleted'))}/>} {dialog==='reassessment'&&<ReassessmentDialog t={t} onClose={()=>setDialog(null)} onSave={draft=>run(()=>repository.reassess(record,draft),t('actionCompleted'))}/>} {dialog==='outcome'&&<OutcomeDialog t={t} onClose={()=>setDialog(null)} onSave={draft=>run(()=>repository.complete(record,draft),t('clinicalRecords.outcomeSaved'))}/>} {entryDetail&&<ClinicalEntryDetail entry={entryDetail} t={t} language={language} fmtDate={fmtDate} fmtDateTime={fmtDateTime} canManage={active} onClose={()=>setEntryDetail(null)} onEdit={()=>{const kind=entryDetail.kind;setEntryDetail(null);if(kind==='therapy')return;setDialog(kind==='sample'?'sample':kind)}} onFinishTherapy={entryDetail.kind==='therapy'&&entryDetail.row?.status==='active'&&permissions.canTherapy?()=>{const row=entryDetail.row;setEntryDetail(null);run(()=>repository.finishTherapy(record,row.id,{endedAt:new Date().toISOString().slice(0,10)}),t('actionCompleted'))}:null} onApproveTherapy={entryDetail.kind==='therapy'&&permissions.canTherapy?()=>{const row=entryDetail.row;setEntryDetail(null);run(()=>repository.updateTherapyApproval(record,row.id,'approved'),t('actionCompleted'))}:null} onRejectTherapy={entryDetail.kind==='therapy'&&permissions.canTherapy?()=>{const row=entryDetail.row;setEntryDetail(null);run(()=>repository.updateTherapyApproval(record,row.id,'rejected'),t('actionCompleted'))}:null} onRecordAdministration={entryDetail.kind==='therapy'&&permissions.canTherapy?draft=>{const row=entryDetail.row;setEntryDetail(null);run(()=>repository.recordAdministration(record,row.id,draft),t('actionCompleted'))}:null}/>}</div>}

function approvalStatusLabel(status,language){return {pending:language==='el'?'Εκκρεμεί έγκριση':'Pending approval',approved:language==='el'?'Εγκρίθηκε':'Approved',rejected:language==='el'?'Απορρίφθηκε':'Rejected',not_required:language==='el'?'Δεν απαιτείται':'Not required'}[status]||status||'—'}
function administrationStatusLabel(status,language){return {administered:language==='el'?'Χορηγήθηκε':'Administered',withheld:language==='el'?'Παρακρατήθηκε':'Withheld',refused:language==='el'?'Αρνήθηκε':'Refused'}[status]||status||'—'}
function ClinicalEntryDetail({entry,t,language,fmtDate,fmtDateTime,canManage,onClose,onEdit,onFinishTherapy,onApproveTherapy,onRejectTherapy,onRecordAdministration}){const [showAdminForm,setShowAdminForm]=useState(false);const row=entry.row||{};const titleMap={sample:language==='el'?'Λεπτομέρειες δείγματος':'Sample details',therapy:language==='el'?'Λεπτομέρειες αντιμικροβιακής αγωγής':'Antimicrobial therapy details',reassessment:language==='el'?'Λεπτομέρειες επανεκτίμησης':'Reassessment details'};const fields=entry.kind==='sample'?[[language==='el'?'Κωδικός δείγματος':'Sample code',row.id],[t('sampleType'),clinicalValueLabel(row.type||row.sampleType,language,t)],[t('status'),clinicalValueLabel(row.result||row.status||'pending',language,t)],[t('organism'),row.organism||'—'],['AMR',row.resistance||'—']]:entry.kind==='therapy'?[[language==='el'?'Αντιμικροβιακό':'Antimicrobial',row.antimicrobial],[language==='el'?'Δόση':'Dose',row.dose],[language==='el'?'Οδός χορήγησης':'Route',clinicalValueLabel(row.route,language,t)],[language==='el'?'Έναρξη':'Started',fmtDate(row.startedAt)],[t('status'),clinicalValueLabel(row.status||'active',language,t)],[language==='el'?'Stewardship':'Stewardship',approvalStatusLabel(row.approvalStatus,language)]]:[[language==='el'?'Ημερομηνία':'Date',fmtDate(row.date)],[t('status'),clinicalValueLabel(row.status,language,t)],[language==='el'?'Σημειώσεις':'Notes',row.notes||'—'],[language==='el'?'Επόμενη επανεκτίμηση':'Next review',fmtDate(row.nextReviewDue)]];const pendingApproval=row.approvalStatus==='pending';const canAdminister=row.status==='active'&&!pendingApproval&&row.approvalStatus!=='rejected';return <ObserverDialog title={titleMap[entry.kind]||t('details')} onClose={onClose}><div className="detail-grid clinical-entry-detail-grid">{fields.map(([label,value])=><Detail key={label} label={label} value={value}/>)}</div>{entry.kind==='therapy'&&<div className="record-section-header"><div><span className="eyebrow">{language==='el'?'Πραγματικές χορηγήσεις':'Actual administrations'}</span></div></div>}{entry.kind==='therapy'&&(row.administrations?.length?<div className="record-table-wrap"><table className="record-table"><thead><tr><th>{language==='el'?'Ημερομηνία':'Date'}</th><th>{language==='el'?'Δόση':'Dose'}</th><th>{language==='el'?'Οδός':'Route'}</th><th>{t('status')}</th></tr></thead><tbody>{row.administrations.map(a=><tr key={a.id}><td>{fmtDateTime?fmtDateTime(a.administeredAt):fmtDate(a.administeredAt)}</td><td>{a.dose||'—'}</td><td>{a.route||'—'}</td><td>{administrationStatusLabel(a.status,language)}</td></tr>)}</tbody></table></div>:<div className="inline-empty">{language==='el'?'Δεν έχει καταγραφεί ακόμη χορήγηση.':'No administration recorded yet.'}</div>)}{entry.kind==='therapy'&&pendingApproval&&<div className="entry-detail-note">{language==='el'?'Περιορισμένο αντιβιοτικό — απαιτείται έγκριση stewardship πριν καταγραφεί χορήγηση.':'Restricted antibiotic — stewardship approval is required before an administration can be recorded.'}</div>}<div className="dialog-actions">{entry.kind==='sample'&&canManage&&<span className="entry-detail-note">{language==='el'?'Η καταχώριση αποτελέσματος/διόρθωση γίνεται από το Εργαστήριο ώστε να διατηρείται πλήρες audit trail.':'Results and corrections are managed by Laboratory to preserve the audit trail.'}</span>}{entry.kind==='reassessment'&&canManage&&<span className="entry-detail-note">{language==='el'?'Οι επανεκτιμήσεις παραμένουν ιστορικές. Για αλλαγή καταχωρείται νέα επανεκτίμηση.':'Reassessments remain historical; record a new reassessment for a change.'}</span>}{entry.kind==='therapy'&&pendingApproval&&onRejectTherapy&&<Button variant="secondary" onClick={onRejectTherapy}>{language==='el'?'Απόρριψη':'Reject'}</Button>}{entry.kind==='therapy'&&pendingApproval&&onApproveTherapy&&<Button variant="secondary" onClick={onApproveTherapy}>{language==='el'?'Έγκριση':'Approve'}</Button>}{entry.kind==='therapy'&&canAdminister&&onRecordAdministration&&<Button variant="secondary" onClick={()=>setShowAdminForm(true)}>{language==='el'?'Καταγραφή χορήγησης':'Record administration'}</Button>}{entry.kind==='therapy'&&onFinishTherapy&&<Button variant="secondary" onClick={onFinishTherapy}>{language==='el'?'Ολοκλήρωση αγωγής':'End therapy'}</Button>}{entry.kind==='reassessment'&&canManage&&<Button onClick={onEdit}>{language==='el'?'Νέα επανεκτίμηση':'New reassessment'}</Button>}</div>{showAdminForm&&<AdministrationDialog t={t} language={language} onClose={()=>setShowAdminForm(false)} onSave={draft=>{setShowAdminForm(false);onRecordAdministration?.(draft)}}/>}</ObserverDialog>}
function AdministrationDialog({t,language,onClose,onSave}){const [d,setD]=useState({administeredAt:new Date().toISOString().slice(0,10),dose:'',route:'',status:'administered',withheldReason:'',notes:''});const valid=d.status==='administered'||d.withheldReason.trim();return <SimpleDialog title={language==='el'?'Καταγραφή χορήγησης':'Record administration'} t={t} onClose={onClose} onSave={()=>onSave(d)} disabled={!valid}><ManualDateField label={language==='el'?'Ημερομηνία χορήγησης':'Administration date'} value={d.administeredAt} onChange={v=>setD(x=>({...x,administeredAt:v}))}/><label><span>{language==='el'?'Δόση':'Dose'}</span><input value={d.dose} onChange={e=>setD(x=>({...x,dose:e.target.value}))}/></label><label><span>{language==='el'?'Οδός':'Route'}</span><input value={d.route} onChange={e=>setD(x=>({...x,route:e.target.value}))}/></label><label><span>{language==='el'?'Κατάσταση':'Status'}</span><select value={d.status} onChange={e=>setD(x=>({...x,status:e.target.value,withheldReason:e.target.value==='administered'?'':x.withheldReason}))}><option value="administered">{language==='el'?'Χορηγήθηκε':'Administered'}</option><option value="withheld">{language==='el'?'Παρακρατήθηκε':'Withheld'}</option><option value="refused">{language==='el'?'Αρνήθηκε ο ασθενής':'Refused by patient'}</option></select></label>{d.status!=='administered'&&<label className="entry-span-2"><span>{language==='el'?'Λόγος (υποχρεωτικό)':'Reason (required)'}</span><textarea value={d.withheldReason} onChange={e=>setD(x=>({...x,withheldReason:e.target.value}))}/></label>}<label className="entry-span-2"><span>{language==='el'?'Σημειώσεις':'Notes'}</span><textarea value={d.notes} onChange={e=>setD(x=>({...x,notes:e.target.value}))}/></label></SimpleDialog>}
function escapeReport(value){return String(value??'—').replace(/[&<>"]/g,ch=>ch==='&'?'&amp;':ch==='<'?'&lt;':ch==='>'?'&gt;':'&quot;')}
function printSurveillanceReport(record,{language='el',fmtDate,fmtDateTime}){
  const esc=escapeReport
  const L=(el,en)=>language==='el'?el:en
  const rows=(items,empty='—')=>items?.length?items.map(x=>`<li>${esc(x)}</li>`).join(''):`<li>${empty}</li>`
  const samples=(record.samples||[]).map(s=>`<tr><td>${esc(fmtDate(s.collectedAt||s.requestedAt))}</td><td>${esc(s.type||s.sampleType)}</td><td>${esc(s.sampleCode||s.id)}</td><td>${esc(clinicalTerm(s.result,language))}</td><td>${esc(s.organism)}</td><td>${esc(s.resistance||s.amr)}</td></tr>`).join('')
  const therapy=(record.therapy||[]).map(x=>`<tr><td>${esc(x.antimicrobial||x.drug)}</td><td>${esc(x.dose)}</td><td>${esc(x.route)}</td><td>${esc(fmtDate(x.startedAt||x.startDate))}</td><td>${esc(fmtDate(x.endedAt||x.endDate))}</td></tr>`).join('')
  const timeline=(record.timeline||[]).slice().sort((a,b)=>new Date(a.at||a.createdAt)-new Date(b.at||b.createdAt)).map(x=>`<tr><td>${esc(fmtDateTime(x.at||x.createdAt))}</td><td>${esc(x.label||x.type)}</td><td>${esc(clinicalTerm(x.value||x.detail||x.notes,language))}</td></tr>`).join('')
  const html=`<!doctype html><html><head><meta charset="utf-8"><title>${L('Αναφορά επιτήρησης','Surveillance report')}</title><style>@page{size:A4;margin:14mm}body{font:12px Arial,sans-serif;color:#17324a}h1{font-size:21px;margin:0 0 4px}h2{font-size:14px;border-bottom:1px solid #cbd8e3;padding-bottom:5px;margin:20px 0 8px}.muted{color:#687b8d}.grid{display:grid;grid-template-columns:1fr 1fr;gap:6px 18px}.field{padding:6px 0;border-bottom:1px solid #edf1f4}.field b{display:block;font-size:10px;color:#687b8d;text-transform:uppercase;margin-bottom:2px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:6px;border-bottom:1px solid #dfe7ed;vertical-align:top}th{font-size:10px;color:#607487;background:#f5f8fa}ul{margin:5px 0;padding-left:18px}.footer{margin-top:24px;padding-top:8px;border-top:1px solid #cbd8e3;color:#687b8d;font-size:10px}@media print{button{display:none}}</style></head><body><h1>${L('Αναλυτική αναφορά επιτήρησης','Detailed surveillance report')}</h1><div class="muted">${L('Limoxis Observer · Κλινική επιτήρηση','Limoxis Observer · Clinical surveillance')}</div><h2>${L('Στοιχεία επεισοδίου','Episode details')}</h2><div class="grid"><div class="field"><b>${L('Ασθενής','Patient')}</b>${esc(record.patient||record.patientName)}</div><div class="field"><b>${L('Κωδικός ασθενούς','Patient code')}</b>${esc(record.patientId)}</div><div class="field"><b>${L('Τμήμα','Department')}</b>${esc(record.department)}</div><div class="field"><b>${L('Έναρξη επιτήρησης','Surveillance start')}</b>${esc(fmtDate(record.startedAt))}</div><div class="field"><b>${L('Κατάσταση','Status')}</b>${esc(clinicalTerm(record.status,language))}</div><div class="field"><b>${L('Λόγος επιτήρησης','Surveillance reason')}</b>${esc(record.reason)}</div></div><h2>${L('Κλινική αξιολόγηση','Clinical assessment')}</h2><div class="grid"><div class="field"><b>${L('Ημερομηνία αξιολόγησης','Assessment date')}</b>${esc(fmtDate(record.assessment?.date))}</div><div class="field"><b>${L('Κλινική ταξινόμηση','Clinical classification')}</b>${esc(clinicalTerm(record.assessment?.classification,language))}</div></div><b>${L('Σημεία / συμπτώματα','Signs / symptoms')}</b><ul>${rows((record.assessment?.symptoms||[]).map(x=>clinicalTerm(x,language)))}</ul><b>${L('Παράγοντες κινδύνου','Risk factors')}</b><ul>${rows((record.assessment?.riskFactors||[]).map(x=>clinicalTerm(x,language)))}</ul><h2>${L('Μικροβιολογικά δείγματα','Microbiology samples')}</h2><table><thead><tr><th>${L('Ημερομηνία','Date')}</th><th>${L('Τύπος','Type')}</th><th>${L('Κωδικός','Code')}</th><th>${L('Αποτέλεσμα','Result')}</th><th>${L('Μικροοργανισμός','Organism')}</th><th>AMR</th></tr></thead><tbody>${samples||`<tr><td colspan="6">${L('Δεν υπάρχουν καταχωρισμένα δείγματα.','No samples recorded.')}</td></tr>`}</tbody></table><h2>${L('Απομόνωση','Isolation')}</h2><div class="grid"><div class="field"><b>${L('Κατάσταση','Status')}</b>${esc(record.isolation?clinicalTerm(record.isolation.status||'yes',language):L('Δεν απαιτείται / δεν έχει καταχωριστεί','Not required / not recorded'))}</div><div class="field"><b>${L('Έναρξη','Start')}</b>${esc(fmtDate(record.isolation?.startedAt))}</div></div><h2>${L('Αντιμικροβιακή αγωγή','Antimicrobial therapy')}</h2><table><thead><tr><th>${L('Φάρμακο','Drug')}</th><th>${L('Δόση','Dose')}</th><th>${L('Οδός','Route')}</th><th>${L('Έναρξη','Start')}</th><th>${L('Λήξη','End')}</th></tr></thead><tbody>${therapy||`<tr><td colspan="5">${L('Δεν έχει καταχωριστεί αγωγή.','No therapy recorded.')}</td></tr>`}</tbody></table><h2>${L('Χρονολογικό ιστορικό','Chronological history')}</h2><table><thead><tr><th>${L('Ημερομηνία / ώρα','Date / time')}</th><th>${L('Ενέργεια','Action')}</th><th>${L('Λεπτομέρειες','Details')}</th></tr></thead><tbody>${timeline||`<tr><td colspan="3">${L('Δεν υπάρχουν συμβάντα.','No events recorded.')}</td></tr>`}</tbody></table><div class="footer">${L('Η αναφορά δημιουργήθηκε από το Limoxis Observer.','Report generated by Limoxis Observer.')} · ${esc(new Date().toLocaleString(language==='el'?'el-GR':'en-GB'))}</div><script>window.onload=()=>setTimeout(()=>window.print(),150)</script></body></html>`
  const win=window.open('','_blank')
  if(!win){window.alert(L('Το πρόγραμμα περιήγησης εμπόδισε το άνοιγμα της αναφοράς. Επιτρέψτε τα αναδυόμενα παράθυρα για το Limoxis Observer.','The browser blocked the report window. Allow pop-ups for Limoxis Observer.'));return}
  win.document.open();win.document.write(html);win.document.close()
}

function StagePanel({icon:Icon,title,action,children}){return <section className="clinical-panel full-panel"><div className="record-section-header"><div>{Icon&&<Icon size={17}/>}<strong>{title}</strong></div>{action}</div>{children}</section>}
function clinicalTerm(value,language='el'){
  if(value==null||value==='')return '—'
  const key=String(value).trim().toUpperCase()
  const el={UNDETERMINED:'Δεν έχει ακόμη καθοριστεί',PENDING:'Εκκρεμεί',POSITIVE:'Θετικό',NEGATIVE:'Αρνητικό',FEVER:'Πυρετός',CHILLS:'Ρίγος',RIGORS:'Έντονο ρίγος',ICU_STAY:'Νοσηλεία σε ΜΕΘ',ICU:'Νοσηλεία σε ΜΕΘ',DEVICE:'Παρουσία επεμβατικής συσκευής',RECENT_SURGERY:'Πρόσφατη χειρουργική επέμβαση',IMMUNOSUPPRESSION:'Ανοσοκαταστολή',ANTIBIOTIC_EXPOSURE:'Πρόσφατη έκθεση σε αντιμικροβιακά',YES:'Ναι',NO:'Όχι',Y:'Ναι',N:'Όχι',P:'Θετικό',R:'Ανθεκτικό',S:'Ευαίσθητο',I:'Ευαίσθητο με αυξημένη έκθεση'}
  const en={UNDETERMINED:'Not yet determined',PENDING:'Pending',POSITIVE:'Positive',NEGATIVE:'Negative',FEVER:'Fever',CHILLS:'Chills',RIGORS:'Rigors',ICU_STAY:'ICU stay',ICU:'ICU stay',DEVICE:'Invasive device present',RECENT_SURGERY:'Recent surgery',IMMUNOSUPPRESSION:'Immunosuppression',ANTIBIOTIC_EXPOSURE:'Recent antimicrobial exposure',YES:'Yes',NO:'No',Y:'Yes',N:'No',P:'Positive',R:'Resistant',S:'Susceptible',I:'Susceptible, increased exposure'}
  return (language==='el'?el:en)[key]||String(value).replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())
}
function TagList({title,items=[],t:_t,language}){if(!items?.length)return null;return <><h4>{title}</h4><div className="tag-row">{items.map(x=><span className="clinical-tag" key={x}>{clinicalTerm(x,language)}</span>)}</div></>}
function ClinicalSnapshot({record,t,language,fmtDate}){const latest=record?.samples?.find(x=>x.organism)||record?.samples?.[0];const assessment=record?.assessment;const therapy=record?.therapy||[];const reassessments=record?.reassessments||[];const lastReview=reassessments[reassessments.length-1];return <section className="record-section clinical-data-overview"><div className="record-section-header"><div><h3>{language==='el'?'Κλινικά δεδομένα επιτήρησης':'Surveillance clinical data'}</h3><p>{language==='el'?'Συγκεντρωτική εικόνα της επιλεγμένης επιτήρησης.':'Consolidated view of the selected surveillance episode.'}</p></div></div><div className="clinical-data-cards"><ClinicalDataCard icon={ShieldCheck} title={language==='el'?'Κλινική αξιολόγηση':'Clinical assessment'} state={assessment?(language==='el'?'Τεκμηριωμένη':'Documented'):(language==='el'?'Δεν έχει τεκμηριωθεί':'Not documented')}><ClinicalDatum label={language==='el'?'Ταξινόμηση':'Classification'} value={clinicalTerm(assessment?.classification,language)}/><ClinicalDatum label={language==='el'?'Σύνοψη':'Summary'} value={assessment?.summary||'—'}/></ClinicalDataCard><ClinicalDataCard icon={Microscope} title={language==='el'?'Μικροβιολογία':'Microbiology'} state={record?.samples?.length?`${record.samples.length} ${language==='el'?'δείγμα(τα)':'sample(s)'}`:(language==='el'?'Χωρίς δείγματα':'No samples')}><ClinicalDatum label={language==='el'?'Τελευταίο εύρημα':'Latest finding'} value={latest?.organism||t(latest?.result||'pending')}/><ClinicalDatum label={language==='el'?'AMR – Αντοχή στα αντιμικροβιακά':'AMR – Antimicrobial resistance'} value={latest?.resistance||record?.resistance||'—'}/></ClinicalDataCard><ClinicalDataCard icon={Pill} title={language==='el'?'Αντιμικροβιακή αγωγή':'Antimicrobial therapy'} state={therapy.length?`${therapy.length} ${language==='el'?'αγωγή(ές)':'therapy item(s)'}`:(language==='el'?'Δεν καταγράφηκε':'Not recorded')}><ClinicalDatum label={language==='el'?'Τρέχουσα αγωγή':'Current therapy'} value={therapy.map(x=>x.antimicrobial).filter(Boolean).join(', ')||'—'}/></ClinicalDataCard><ClinicalDataCard icon={RefreshCcw} title={language==='el'?'Επανεκτίμηση':'Reassessment'} state={record?.reviewDue?`${language==='el'?'Επόμενη':'Next'}: ${fmtDate(record.reviewDue)}`:'—'}><ClinicalDatum label={language==='el'?'Τελευταία κατάσταση':'Latest status'} value={clinicalTerm(lastReview?.status,language)}/><ClinicalDatum label={language==='el'?'Επόμενη επανεκτίμηση':'Next review'} value={fmtDate(record?.reviewDue)}/></ClinicalDataCard></div></section>}
function ClinicalDataCard({icon:Icon,title,state,children}){return <article className="clinical-data-card"><header><span className="clinical-data-icon"><Icon size={17}/></span><div><h4>{title}</h4><small>{state}</small></div></header><div className="clinical-data-card-body">{children}</div></article>}
function ClinicalDatum({label,value}){return <div className="clinical-datum"><span>{label}</span><strong>{value||'—'}</strong></div>}
function clinicalValueLabel(value,language,t){
  if(value===null||value===undefined||value==='')return '—'
  const labels={FEVER:language==='el'?'Πυρετός':'Fever',CHILLS:language==='el'?'Ρίγος':'Chills',ICU_STAY:language==='el'?'Νοσηλεία σε ΜΕΘ':'ICU stay',
    undetermined:['Δεν έχει ακόμη καθοριστεί','Not yet determined'],
    created:['Δημιουργήθηκε','Created'],
    no:['Όχι','No'],
    yes:['Ναι','Yes'],
    pending:['Εκκρεμεί','Pending'],
    infection:['Λοίμωξη','Infection'],
    colonization:['Αποικισμός','Colonization'],
    no_infection:['Δεν τεκμηριώνεται λοίμωξη','No evidence of infection'],
    under_investigation:['Υπό διερεύνηση','Under investigation'],
    probable_infection:['Πιθανή λοίμωξη','Probable infection'],
    confirmed_infection:['Επιβεβαιωμένη λοίμωξη','Confirmed infection'],
  }
  const mapped=labels[String(value)]
  if(mapped)return mapped[language==='el'?0:1]
  const translated=t(String(value))
  return translated===String(value)?String(value).replaceAll('_',' '):translated
}
function timelineLabel(type,language,t){const labels={created:['Δημιουργία επιτήρησης','Surveillance created'],surveillance_start:['Έναρξη επιτήρησης','Surveillance started'],clinical_assessment:['Κλινική αξιολόγηση','Clinical assessment'],sample_requested:['Αίτημα δείγματος','Sample requested'],sample_collected:['Λήψη δείγματος','Sample collected'],sample_result:['Αποτέλεσμα δείγματος','Sample result'],isolation_started:['Έναρξη απομόνωσης','Isolation started'],isolation_not_required:['Δεν απαιτείται απομόνωση','Isolation not required'],therapy_started:['Έναρξη αντιμικροβιακής αγωγής','Antimicrobial therapy started'],reassessment:['Επανεκτίμηση','Reassessment'],outcome:['Έκβαση','Outcome'],surveillance_closed:['Ολοκλήρωση επιτήρησης','Surveillance closed']};return labels[type]?.[language==='el'?0:1]||t(type)||String(type||'—').replaceAll('_',' ')}
function Timeline({record,t,language,fmtDateTime}){const rows=[...(record?.timeline||[])].sort((a,b)=>new Date(b.at||0)-new Date(a.at||0));return <section className="record-section patient-history-section"><div className="record-section-header"><div><h3>{language==='el'?'Ιστορικό επιτήρησης':'Surveillance history'}</h3><p>{language==='el'?'Χρονολογικό ιστορικό των κλινικών ενεργειών.':'Chronological audit trail of clinical actions.'}</p></div></div>{rows.length?<div className="patient-history-list">{rows.map((x,i)=><article className="patient-history-event" key={`${x.at||'event'}-${i}`}><div className="history-rail"><span/></div><div className="history-event-main"><div className="history-event-heading"><strong>{timelineLabel(x.type,language,t)}</strong><time>{fmtDateTime(x.at)}</time></div>{x.detail&&<p>{clinicalValueLabel(x.detail,language,t)}</p>}<div className="history-event-meta">{(x.actor||x.actorId)&&<span>{language==='el'?'Χρήστης':'User'}: {x.actor||x.actorId}</span>}{x.sampleId&&<span>{language==='el'?'Δείγμα':'Sample'}: {x.sampleId}</span>}</div></div></article>)}</div>:<div className="inline-empty">{language==='el'?'Δεν υπάρχουν ακόμη καταγεγραμμένες ενέργειες.':'No recorded events yet.'}</div>}</section>}

function CompletedReport({record,t,fmtDate,fmtDateTime}){const positive=(record.samples||[]).filter(x=>x.result==='positive');return <article className="surveillance-final-report"><header className="final-report-title"><div><span>{t('clinicalRecords.finalSurveillanceReport')}</span><h2>{record.patient}</h2><p>{record.id} · {fmtDate(record.startedAt)} → {fmtDate(record.completedAt||record.outcome?.date)}</p></div></header><Narrative number="01" title={t('clinicalAssessment')} text={record.assessment?.summary||t('clinicalRecords.notDocumented')}/><Narrative number="02" title={t('haiAmr')} text={record.haiClassification?`${record.haiClassification.type||''} · ${t(record.haiClassification.status)}`:t('clinicalRecords.notDocumented')}/><Narrative number="03" title={t('microbiology')} text={positive.map(x=>x.organism).filter(Boolean).join(', ')||t('clinicalRecords.noPositiveFindings')}/><Narrative number="04" title={t('therapy')} text={(record.therapy||[]).map(x=>x.antimicrobial).join(', ')||t('clinicalRecords.noTherapyRecorded')}/><Narrative number="05" title={t('isolation')} text={record.isolation?t(record.isolation.status):t('clinicalRecords.noIsolationRecorded')}/><Narrative number="06" title={t('reassessment')} text={(record.reassessments||[]).map(x=>`${fmtDate(x.date)}: ${t(x.status)}`).join(' · ')||t('clinicalRecords.noReassessmentRecorded')}/><Narrative number="07" title={t('outcome')} text={record.outcome?`${t(record.outcome.status)} · ${fmtDate(record.outcome.date)}`:t('clinicalRecords.notDocumented')}/><section className="final-report-course"><div className="final-report-section-heading"><span>08</span><h3>{t('clinicalRecords.courseSummary')}</h3></div><div className="course-timeline">{(record.timeline||[]).map((x,i)=><div key={`${x.at}-${i}`} className="course-event"><time>{fmtDateTime(x.at)}</time><span>{t(x.type)||x.type}</span><strong>{x.actor||x.actorId||'—'}</strong><p>{x.detail||'—'}</p></div>)}</div></section></article>}
function Narrative({number,title,text}){return <section className="final-report-narrative"><div className="final-report-section-heading"><span>{number}</span><h3>{title}</h3></div><p>{text}</p></section>}
function SimpleDialog({title,t,onClose,onSave,children,disabled=false}){return <ObserverDialog title={title} width="wide" onClose={onClose}><div className="entry-grid">{children}</div><div className="dialog-actions"><Button variant="secondary" onClick={onClose}>{t('cancel')}</Button><SaveButton disabled={disabled} onClick={onSave}>{t('save')}</SaveButton></div></ObserverDialog>}
function AssessmentDialog({t,record,symptomRows=[],riskRows=[],onClose,onSave}){
  const {language}=useLanguage(),a=record.assessment||{}
  const symptomOptions=symptomRows.length?symptomRows:[['Πυρετός','Fever'],['Ρίγος','Chills'],['Υπόταση','Hypotension'],['Βήχας','Cough'],['Δύσπνοια','Dyspnea'],['Δυσουρία','Dysuria'],['Άλγος','Pain'],['Ερύθημα / εκροή','Erythema / drainage']]
  const riskOptions=riskRows.filter(row=>!/(καθετήρ|catheter|device|αερισμ|ventilat|γραμμή|line)/i.test(String(row[0]||'')+' '+String(row[1]||'')))
  const questions=[['recentSurgery',language==='el'?'Πρόσφατη χειρουργική επέμβαση':'Recent surgery'],['currentAntibiotics',language==='el'?'Τρέχουσα ή πρόσφατη αντιμικροβιακή αγωγή':'Current or recent antimicrobial therapy'],['recentHospitalization',language==='el'?'Πρόσφατη νοσηλεία':'Recent hospitalization'],['transferFromFacility',language==='el'?'Μεταφορά από άλλη μονάδα υγείας':'Transfer from another healthcare facility'],['knownMdro',language==='el'?'Γνωστό ιστορικό πολυανθεκτικού μικροοργανισμού (MDRO)':'Known multidrug-resistant organism (MDRO) history'],['immunosuppression',language==='el'?'Ανοσοκαταστολή':'Immunosuppression'],['recentProcedure',language==='el'?'Πρόσφατη επεμβατική πράξη':'Recent invasive procedure']]
  const [d,setD]=useState({date:String(a.date||new Date().toISOString()).slice(0,10),classification:a.classification||'undetermined',summary:a.summary||'',signsSymptoms:a.signsSymptoms||a.symptoms||[],riskFactors:a.riskFactors||[],screening:{...Object.fromEntries(questions.map(([id])=>[id,'unknown'])),...(a.screening||{})}})
  const toggle=(key,value)=>setD(x=>({...x,[key]:x[key].includes(value)?x[key].filter(v=>v!==value):[...x[key],value]}))
  return <SimpleDialog title={language==='el'?'Κλινική αξιολόγηση επιτήρησης':'Surveillance clinical assessment'} t={t} onClose={onClose} onSave={()=>onSave(d)}>
    <ManualDateField label={language==='el'?'Ημερομηνία αξιολόγησης':'Assessment date'} value={d.date} onChange={v=>setD(x=>({...x,date:v}))}/>
    <label><span>{language==='el'?'Κλινική ταξινόμηση':'Clinical classification'}</span><select value={d.classification} onChange={e=>setD(x=>({...x,classification:e.target.value}))}><option value="infection">{language==='el'?'Λοίμωξη':'Infection'}</option><option value="colonization">{language==='el'?'Αποικισμός':'Colonization'}</option><option value="no_infection">{language==='el'?'Δεν τεκμηριώνεται λοίμωξη':'No evidence of infection'}</option><option value="undetermined">{language==='el'?'Δεν έχει ακόμη καθοριστεί':'Not yet determined'}</option></select></label>
    <div className="entry-span-2 clinical-check-grid library-clinical-grid"><LibraryMultiSelect title={language==='el'?'Σημεία / συμπτώματα':'Signs / symptoms'} rows={symptomOptions} selected={d.signsSymptoms} onToggle={v=>toggle('signsSymptoms',v)} language={language}/><LibraryMultiSelect title={language==='el'?'Παράγοντες κινδύνου':'Risk factors'} rows={riskOptions} selected={d.riskFactors} onToggle={v=>toggle('riskFactors',v)} language={language}/></div>
    <section className="entry-span-2 screening-questionnaire"><h4>{language==='el'?'Ερωτηματολόγιο αρχικής επιτήρησης':'Initial surveillance questionnaire'}</h4><div className="questionnaire-grid">{questions.map(([id,label])=><div key={id} className="questionnaire-item"><span>{label}</span><select value={d.screening[id]} onChange={e=>setD(x=>({...x,screening:{...x.screening,[id]:e.target.value}}))}><option value="unknown">{language==='el'?'Άγνωστο':'Unknown'}</option><option value="yes">{language==='el'?'Ναι':'Yes'}</option><option value="no">{language==='el'?'Όχι':'No'}</option></select></div>)}</div></section>
    <label className="entry-span-2"><span>{language==='el'?'Κλινική σύνοψη':'Clinical summary'}</span><textarea rows={4} value={d.summary} onChange={e=>setD(x=>({...x,summary:e.target.value}))}/></label>
  </SimpleDialog>
}
function LibraryMultiSelect({title,rows=[],selected=[],onToggle,language}){const [open,setOpen]=useState(false),[query,setQuery]=useState('');const valueOf=row=>row?.[2]?.id||row?.[2]?.code||row?.[0]||row?.[1]||'';const selectedRows=rows.filter(row=>selected.includes(valueOf(row)));const q=query.trim().toLocaleLowerCase();const filtered=rows.filter(row=>!q||String(language==='el'?(row[0]||row[1]):(row[1]||row[0])).toLocaleLowerCase().includes(q));return <section className="clinical-checklist library-checklist clinical-library-multiselect"><h4>{title}</h4><button type="button" className="clinical-library-trigger" aria-expanded={open} onClick={()=>setOpen(v=>!v)}><span>{selectedRows.length?(language==='el'?selectedRows.length+' επιλεγμένα':selectedRows.length+' selected'):(language==='el'?'Επιλέξτε από τη λίστα':'Select from list')}</span><span aria-hidden="true">⌄</span></button>{open&&<div className="clinical-library-menu"><input className="clinical-library-search" value={query} onChange={e=>setQuery(e.target.value)} placeholder={language==='el'?'Αναζήτηση...':'Search...'}/><div className="clinical-library-options">{filtered.map(row=>{const value=valueOf(row),label=language==='el'?(row[0]||row[1]):(row[1]||row[0]);return <label key={value} className={selected.includes(value)?'selected':''}><input type="checkbox" checked={selected.includes(value)} onChange={()=>onToggle(value)}/><span>{label}</span></label>})}</div></div>}{selectedRows.length>0&&<div className="clinical-library-selected">{selectedRows.map(row=>{const value=valueOf(row),label=language==='el'?(row[0]||row[1]):(row[1]||row[0]);return <button type="button" key={value} onClick={()=>onToggle(value)}>{label}<span>×</span></button>})}</div>}</section>}
function DeviceDialog({t,items=[],onAddLibraryItem,onClose,onSave}){const {language}=useLanguage();const defaults=[['Κεντρικός φλεβικός καθετήρας (CVC)','Central venous catheter (CVC)'],['Ουροκαθετήρας','Urinary catheter'],['Μηχανικός αερισμός','Mechanical ventilation'],['Περιφερικός φλεβικός καθετήρας','Peripheral venous catheter']];const options=items.length?items:defaults;const blank=()=>({type:options[0]?.[0]||'',insertedAt:new Date().toISOString().slice(0,10),site:'',notes:''});const [rows,setRows]=useState([blank()]);const [adding,setAdding]=useState(false),[newName,setNewName]=useState('');async function add(){const name=newName.trim();if(!name)return;const row=[name,name,{system:false,locked:false,source:'Hospital',version:'local'}];const saved=await onAddLibraryItem?.(row)||row;setRows(list=>list.map((x,i)=>i===0?{...x,type:saved[language==='el'?0:1]||saved[0]}:x));setNewName('');setAdding(false)}const update=(i,key,value)=>setRows(list=>list.map((x,n)=>n===i?{...x,[key]:value}:x));const save=async()=>{for(const row of rows.filter(x=>x.type))await onSave(row)};return <SimpleDialog title={language==='el'?'Επεμβατικές συσκευές / παράγοντες κινδύνου':'Invasive devices / risk factors'} t={t} onClose={onClose} onSave={save} disabled={!rows.some(x=>x.type&&x.insertedAt)}>{rows.map((d,i)=><div className="entry-span-2 therapy-entry-card" key={i}><div className="entry-grid"><label><span>{language==='el'?'Τύπος συσκευής':'Device type'}</span><select value={d.type} onChange={e=>{if(e.target.value==='__new__')setAdding(true);else update(i,'type',e.target.value)}}>{options.map((x,n)=><option key={x[2]?.id||n} value={x[language==='el'?0:1]||x[0]}>{x[language==='el'?0:1]||x[0]}</option>)}<option value="__new__">{language==='el'?'+ Νέα προσθήκη στη βιβλιοθήκη':'+ Add to library'}</option></select></label><ManualDateField label={language==='el'?'Ημερομηνία τοποθέτησης / έναρξης':'Insertion / start date'} value={d.insertedAt} onChange={v=>update(i,'insertedAt',v)}/><label><span>{language==='el'?'Θέση / σημείο':'Site'}</span><input value={d.site} onChange={e=>update(i,'site',e.target.value)}/></label></div><label><span>{language==='el'?'Σημειώσεις':'Notes'}</span><textarea rows={2} value={d.notes} onChange={e=>update(i,'notes',e.target.value)}/></label>{rows.length>1&&<Button variant="ghost" onClick={()=>setRows(list=>list.filter((_,n)=>n!==i))}>{language==='el'?'Αφαίρεση':'Remove'}</Button>}</div>)}{adding&&<div className="entry-span-2 inline-library-add"><label><span>{language==='el'?'Νέα συσκευή':'New device'}</span><input autoFocus value={newName} onChange={e=>setNewName(e.target.value)}/></label><Button variant="secondary" onClick={add}>{language==='el'?'Προσθήκη στη βιβλιοθήκη':'Add to library'}</Button></div>}<div className="entry-span-2"><Button variant="secondary" onClick={()=>setRows(list=>[...list,blank()])}>{language==='el'?'+ Προσθήκη συσκευής':'+ Add device'}</Button></div></SimpleDialog>}
function SampleDialog({t,title,initialType='',onClose,onSave}){const {language}=useLanguage();const now=new Date(),initialDate=now.toISOString().slice(0,10),initialTime=now.toTimeString().slice(0,5);const [d,setD]=useState({type:initialType||'bloodCulture',source:'',collectionMethod:'',deviceRelated:'unknown',priority:'routine',collectedDate:initialDate,collectedTime:initialTime});const save=()=>onSave({...d,collectedAt:`${d.collectedDate}T${d.collectedTime||'00:00'}`});return <SimpleDialog title={title||t('laboratoryRecords.newSample')} t={t} onClose={onClose} onSave={save} disabled={!d.collectedDate}><label><span>{t('sampleType')}</span><select value={d.type} onChange={e=>setD(x=>({...x,type:e.target.value}))}><option value="bloodCulture">{t('bloodCulture')}</option><option value="urineCulture">{t('urineCulture')}</option><option value="respiratorySample">{t('respiratorySample')}</option><option value="woundCulture">{t('woundCulture')}</option><option value="other">{t('other')}</option></select></label><label><span>{language==='el'?'Ανατομική θέση / προέλευση':'Anatomical site / source'}</span><input value={d.source} onChange={e=>setD(x=>({...x,source:e.target.value}))}/></label><ManualDateField label={t('collectedLabel')} value={d.collectedDate} onChange={v=>setD(x=>({...x,collectedDate:v}))}/><TimeField label={language==='el'?'Ώρα λήψης':'Collection time'} value={d.collectedTime} onChange={v=>setD(x=>({...x,collectedTime:v}))}/><label><span>{language==='el'?'Τρόπος λήψης':'Collection method'}</span><input value={d.collectionMethod} onChange={e=>setD(x=>({...x,collectionMethod:e.target.value}))} placeholder={language==='el'?(d.type==='bloodCulture'?'π.χ. περιφερική φλέβα / κεντρική γραμμή':d.type==='urineCulture'?'π.χ. μέσο ρεύμα / ουροκαθετήρας':'Προαιρετικό'):'Optional sample-specific metadata'}/></label><label><span>{language==='el'?'Συσχέτιση με συσκευή':'Device related'}</span><select value={d.deviceRelated} onChange={e=>setD(x=>({...x,deviceRelated:e.target.value}))}><option value="unknown">{language==='el'?'Άγνωστο / δεν έχει αξιολογηθεί':'Unknown / not assessed'}</option><option value="yes">{language==='el'?'Ναι':'Yes'}</option><option value="no">{language==='el'?'Όχι':'No'}</option></select></label><label><span>{t('priority')}</span><select value={d.priority} onChange={e=>setD(x=>({...x,priority:e.target.value}))}><option value="routine">{t('routine')}</option><option value="urgent">{t('urgent')}</option><option value="critical">{t('critical')}</option></select></label><div className="entry-span-2 inline-empty">{language==='el'?'Στο δείγμα καταγράφονται μόνο στοιχεία λήψης. Η κλινική αξιολόγηση και το ερωτηματολόγιο ανήκουν στην επιτήρηση.':'Only collection metadata are recorded on the sample. Clinical assessment and questionnaires belong to surveillance.'}</div></SimpleDialog>}
function HaiDialog({t,items=[],organizationId,isDemo,onAddLibraryItem,onClose,onSave}){const {language}=useLanguage();const [criteriaSets,setCriteriaSets]=useState(null);useEffect(()=>{let alive=true;loadHaiCriteriaSets(organizationId).then(sets=>{if(alive)setCriteriaSets(sets)}).catch(()=>{});return()=>{alive=false}},[organizationId,isDemo]);
 // Fallback list shown until the centrally-governed criteria sets (master_library_items,
 // library_key 'hai_criteria') load — kept in sync with the same static baseline used as
 // the demo/offline fallback, so the dialog is never empty on first render.
 const staticDefaults=[['CLABSI – Λοίμωξη αιματικής ροής σχετιζόμενη με κεντρικό φλεβικό καθετήρα','CLABSI – Central line-associated bloodstream infection',{source:'ECDC',id:'clabsi'}],['CLABSI (νεογνική/βρεφική ≤1 έτους) – Λοίμωξη αιματικής ροής σχετιζόμενη με κεντρικό καθετήρα','CLABSI (neonatal/infant ≤1 year) – Central line-associated bloodstream infection',{source:'CDC/NHSN',id:'clabsi_neonatal'}],['CAUTI – Ουρολοίμωξη σχετιζόμενη με ουροκαθετήρα','CAUTI – Catheter-associated urinary tract infection',{source:'ECDC',id:'cauti'}],['VAP – Πνευμονία σχετιζόμενη με μηχανικό αερισμό','VAP – Ventilator-associated pneumonia',{source:'ECDC',id:'vap'}],['SSI – Λοίμωξη χειρουργικού πεδίου','SSI – Surgical site infection',{source:'ECDC',id:'ssi'}]];const defaults=criteriaSets?Object.entries(criteriaSets).map(([key,set])=>[set.labelEl,set.labelEn||set.labelEl,{source:set.source||'CDC/NHSN',id:key}]):staticDefaults;const options=items.length?items:defaults;const first=options[0];const [d,setD]=useState({status:'suspected',type:first?.[language==='el'?0:1]||first?.[0]||'',definitionSet:first?.[2]?.source||'ECDC',definitionVersion:first?.[2]?.version||'',criteriaKey:first?.[2]?.id||null,criteriaEvidence:[],rationale:''});const [adding,setAdding]=useState(false),[newName,setNewName]=useState(''),[customSource,setCustomSource]=useState('Hospital');function select(value){if(value==='__new__'){setAdding(true);setD(x=>({...x,type:'',definitionSet:'Hospital',criteriaKey:null,criteriaEvidence:[]}));return}const row=options.find(x=>(x[language==='el'?0:1]||x[0])===value);setD(x=>({...x,type:value,definitionSet:row?.[2]?.source||'ECDC',definitionVersion:row?.[2]?.version||'',criteriaKey:row?.[2]?.id||null,criteriaEvidence:[]}))}async function add(){const name=newName.trim();if(!name)return;const row=[name,name,{system:false,locked:false,source:customSource||'Hospital',version:'local'}];const saved=await onAddLibraryItem?.(row)||row;setD(x=>({...x,type:saved[0],definitionSet:customSource||'Hospital',criteriaKey:null,criteriaEvidence:[]}));setAdding(false);setNewName('')}function toggleCriterion(itemId){setD(x=>({...x,criteriaEvidence:x.criteriaEvidence.includes(itemId)?x.criteriaEvidence.filter(id=>id!==itemId):[...x.criteriaEvidence,itemId]}))}const criteriaSet=d.criteriaKey?haiCriteriaSetForType(d.criteriaKey,criteriaSets||undefined):null;function save(){const criteriaMet=criteriaSet?evaluateHaiCriteria(d.criteriaKey,d.criteriaEvidence,criteriaSets||undefined):null;onSave({...d,criteriaMet})}return <SimpleDialog title={language==='el'?'HAI – Λοίμωξη σχετιζόμενη με την παροχή φροντίδας υγείας':'HAI – Healthcare-associated infection'} t={t} onClose={onClose} onSave={save} disabled={!d.type}><label><span>{language==='el'?'Τύπος / ορισμός επιτήρησης':'Surveillance type / definition'}</span><select value={adding?'__new__':d.type} onChange={e=>select(e.target.value)}>{options.map((x,i)=><option key={x[2]?.id||i} value={x[language==='el'?0:1]||x[0]}>{x[language==='el'?0:1]||x[0]}</option>)}<option value="__new__">{language==='el'?'+ Νέος ορισμός επιτήρησης':'+ New surveillance definition'}</option></select></label><label><span>{language==='el'?'Κατάσταση':'Status'}</span><select value={d.status} onChange={e=>setD(x=>({...x,status:e.target.value}))}><option value="suspected">{language==='el'?'Ύποπτη':'Suspected'}</option><option value="probable">{language==='el'?'Πιθανή':'Probable'}</option><option value="confirmed">{language==='el'?'Επιβεβαιωμένη':'Confirmed'}</option><option value="excluded">{language==='el'?'Αποκλείστηκε':'Excluded'}</option></select></label><label><span>{language==='el'?'Πηγή ορισμού':'Definition source'}</span><input value={adding?customSource:d.definitionSet} readOnly={!adding} onChange={e=>setCustomSource(e.target.value)} /></label>{adding&&<div className="entry-span-2 inline-library-add"><label><span>{language==='el'?'Νέος ορισμός':'New definition'}</span><input autoFocus value={newName} onChange={e=>setNewName(e.target.value)}/></label><Button variant="secondary" onClick={add}>{language==='el'?'Προσθήκη στη βιβλιοθήκη':'Add to library'}</Button></div>}{criteriaSet&&<div className="entry-span-2 hai-criteria-checklist"><p className="hai-criteria-note">{language==='el'?`Απλοποιημένο checklist βάσει ${criteriaSet.source} — ενδεικτικό εργαλείο υποστήριξης, δεν υποκαθιστά την κλινική κρίση.`:`Simplified checklist based on ${criteriaSet.source} — an indicative decision-support aid, not a substitute for clinical judgement.`}</p>{criteriaSet.groups.map(group=><fieldset key={group.id} className="hai-criteria-group">{group.items.map(item=><label key={item.id} className="hai-criteria-item"><input type="checkbox" checked={d.criteriaEvidence.includes(item.id)} onChange={()=>toggleCriterion(item.id)}/><span>{language==='el'?item.textEl:item.textEn}</span></label>)}</fieldset>)}<div className={`hai-criteria-result ${evaluateHaiCriteria(d.criteriaKey,d.criteriaEvidence,criteriaSets||undefined)?'is-met':'is-pending'}`}>{evaluateHaiCriteria(d.criteriaKey,d.criteriaEvidence,criteriaSets||undefined)?(language==='el'?'Τα κριτήρια πληρούνται με βάση τις επιλογές.':'Criteria are met based on the selections above.'):(language==='el'?'Τα κριτήρια δεν πληρούνται ακόμη.':'Criteria are not yet met.')}</div></div>}<label className="entry-span-2"><span>{language==='el'?'Τεκμηρίωση κριτηρίων':'Criteria rationale'}</span><textarea rows={3} value={d.rationale} onChange={e=>setD(x=>({...x,rationale:e.target.value}))}/></label></SimpleDialog>}
function TherapyDialog({t,antibiotics=[],advancedAntibiotics=[],onClose,onSave}){const {language}=useLanguage();const options=antibiotics.length?antibiotics:demoLibrarySeed.antibiotics;const advancedNames=new Set((advancedAntibiotics.length?advancedAntibiotics:demoLibrarySeed.advancedAntibiotics).flatMap(x=>[x[0],x[1]]));const [rows,setRows]=useState([{antimicrobial:'',dose:'',route:'IV',indication:'',startedAt:new Date().toISOString().slice(0,10),plannedEndAt:'',approvalStatus:'not_required'}]);const update=(i,key,value)=>setRows(list=>list.map((x,n)=>n===i?{...x,[key]:value}:x));const save=async()=>{for(const row of rows.filter(x=>x.antimicrobial))await onSave({...row,isAdvancedAntibiotic:advancedNames.has(row.antimicrobial),stewardshipLinked:advancedNames.has(row.antimicrobial)})};return <SimpleDialog title={language==='el'?'Αντιμικροβιακή αγωγή':'Antimicrobial therapy'} t={t} onClose={onClose} onSave={save} disabled={!rows.some(x=>x.antimicrobial)}>{rows.map((d,i)=><div className="entry-span-2 therapy-entry-card" key={i}><div className="entry-grid"><label><span>{language==='el'?'Αντιμικροβιακό':'Antimicrobial'}</span><select value={d.antimicrobial} onChange={e=>update(i,'antimicrobial',e.target.value)}><option value="">{language==='el'?'Επιλογή από βιβλιοθήκη':'Select from library'}</option>{options.map((x,n)=><option key={x[2]?.id||n} value={x[language==='el'?0:1]||x[0]}>{x[language==='el'?0:1]||x[0]}{advancedNames.has(x[0])||advancedNames.has(x[1])?(language==='el'?' · Προωθημένο':' · Restricted/advanced'):''}</option>)}</select></label><label><span>{language==='el'?'Δόση':'Dose'}</span><input value={d.dose} onChange={e=>update(i,'dose',e.target.value)}/></label><label><span>{language==='el'?'Οδός χορήγησης':'Route'}</span><select value={d.route} onChange={e=>update(i,'route',e.target.value)}><option value="IV">{language==='el'?'Ενδοφλέβια (IV)':'Intravenous (IV)'}</option><option value="PO">{language==='el'?'Από του στόματος (PO)':'Oral (PO)'}</option><option value="IM">{language==='el'?'Ενδομυϊκά (IM)':'Intramuscular (IM)'}</option><option value="other">{language==='el'?'Άλλη':'Other'}</option></select></label><label><span>{language==='el'?'Ένδειξη':'Indication'}</span><input value={d.indication} onChange={e=>update(i,'indication',e.target.value)}/></label><ManualDateField label={language==='el'?'Ημερομηνία έναρξης':'Start date'} value={d.startedAt} onChange={v=>update(i,'startedAt',v)}/><ManualDateField label={language==='el'?'Προγραμματισμένη λήξη':'Planned end date'} optional value={d.plannedEndAt} onChange={v=>update(i,'plannedEndAt',v)}/></div>{advancedNames.has(d.antimicrobial)&&<div className="inline-empty">{language==='el'?'Προωθημένο αντιβιοτικό – η καταχώριση επισημαίνεται αυτόματα για antimicrobial stewardship.':'Advanced/restricted antibiotic – automatically flagged for antimicrobial stewardship.'}</div>}{rows.length>1&&<Button variant="ghost" onClick={()=>setRows(list=>list.filter((_,n)=>n!==i))}>{language==='el'?'Αφαίρεση':'Remove'}</Button>}</div>)}<div className="entry-span-2"><Button variant="secondary" onClick={()=>setRows(list=>[...list,{antimicrobial:'',dose:'',route:'IV',indication:'',startedAt:new Date().toISOString().slice(0,10),plannedEndAt:'',approvalStatus:'not_required'}])}>{language==='el'?'+ Προσθήκη αντιμικροβιακού':'+ Add antimicrobial'}</Button></div></SimpleDialog>}
